-- ************************************** [consumption].[vw_ServiceEntitlementAnalysis]
CREATE VIEW [consumption].[vw_ServiceEntitlementAnalysis] AS
SELECT 
    se.ServiceEntitlementId,
    se.CustomerId,
    c.CustomerName,
    se.ServiceId,
    s.ServiceCode,
    s.ServiceName,
    se.SalesOrderLineId,
    so.OrderNumber,
    se.EntitlementStartDate,
    se.EntitlementEndDate,
    CASE 
        WHEN se.EntitlementEndDate IS NULL THEN 'Active'
        WHEN se.EntitlementEndDate < CAST(GETDATE() AS DATE) THEN 'Expired'
        ELSE 'Upcoming'
    END AS EntitlementStatus,
    DATEDIFF(DAY, se.EntitlementStartDate, ISNULL(se.EntitlementEndDate, CAST(GETDATE() AS DATE))) AS EntitlementDurationDays,
    se.Status,
    se.CreatedAt
FROM dbo.ServiceEntitlement se
INNER JOIN dbo.Customer c ON se.CustomerId = c.CustomerId
INNER JOIN dbo.Service s ON se.ServiceId = s.ServiceId
LEFT JOIN dbo.SalesOrderLine sol ON se.SalesOrderLineId = sol.SalesOrderLineId
LEFT JOIN dbo.SalesOrder so ON sol.SalesOrderId = so.SalesOrderId;
GO
